from collections import defaultdict
from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        # alternating sum bounds: at most 12 per element at even indices (max 75 of them)
        max_possible = 12 * ((n + 1) // 2)
        min_possible = -12 * (n // 2)
        if k > max_possible or k < min_possible:
            return -1

        cap = limit + 1  # sentinel for "exceeded limit"
        # dp[(sum, parity_of_next_index)] = set of products (capped at cap)
        # parity 0 means next element gets sign +, parity 1 means sign -
        dp = defaultdict(set)

        for i, num in enumerate(nums):
            rem = n - i - 1  # elements remaining after this one
            reach = 12 * rem  # max change to alternating sum from remaining elements
            new = defaultdict(set)

            # extend existing subsequences
            for (s, p), prods in list(dp.items()):
                if p == 0:
                    ns = s + num
                    np = 1
                else:
                    ns = s - num
                    np = 0
                # prune states that can never reach k
                if abs(ns - k) > reach:
                    continue
                tgt = new[(ns, np)]
                for pr in prods:
                    v = pr * num
                    if v > cap:
                        v = cap
                    tgt.add(v)

            # start a new subsequence with this element at index 0 (sign +)
            if abs(num - k) <= reach or num == k:
                v = num if num <= cap else cap
                new[(num, 1)].add(v)

            # merge
            for key, prods in new.items():
                dp[key] |= prods

        ans = -1
        for p in (0, 1):
            key = (k, p)
            if key in dp:
                for pr in dp[key]:
                    if pr <= limit and pr > ans:
                        ans = pr
        return ans

