class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        # Precompute F[m]: dict {(sum, product): count} over all length-m strings of digits 1..9
        F = [{(0, 1): 1}]
        for m in range(1, 9):  # r < 10^9 -> at most 9 digits -> free suffix length <= 8
            nd = {}
            for (sm, pr), c in F[-1].items():
                for d in range(1, 10):
                    k = (sm + d, pr * d)
                    if k in nd:
                        nd[k] += c
                    else:
                        nd[k] = c
            F.append(nd)

        def count(n: int) -> int:
            if n <= 0:
                return 0
            s = str(n)
            L = len(s)

            # Count numbers in [1, n] with NO zero digit
            nz = 0
            for k in range(1, L):
                nz += 9 ** k
            ok = True
            for i, ch in enumerate(s):
                c = int(ch)
                if c > 1:
                    nz += (c - 1) * (9 ** (L - 1 - i))
                if c == 0:
                    ok = False
                    break
            if ok:
                nz += 1  # n itself has all nonzero digits
            A = n - nz  # numbers with at least one zero digit -> product 0 -> beautiful

            # Count numbers with all digits 1..9 where product % sum == 0
            B = 0
            # lengths shorter than L: fully free
            for k in range(1, L):
                for (sm, pr), c in F[k].items():
                    if pr % sm == 0:
                        B += c
            # length L, tight against n
            pref_s, pref_p = 0, 1
            valid = True
            for i in range(L):
                c = int(s[i])
                m = L - 1 - i
                Fm = F[m]
                for d in range(1, c):
                    ns = pref_s + d
                    np = pref_p * d
                    for (s2, p2), cnt in Fm.items():
                        if (np * p2) % (ns + s2) == 0:
                            B += cnt
                if c == 0:
                    valid = False
                    break
                pref_s += c
                pref_p *= c
            if valid and pref_p % pref_s == 0:
                B += 1  # n itself

            return A + B

        return count(r) - count(l - 1)

