def main():
    sys.setrecursionlimit(100000)
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx+=1
    M = int(data[idx]); idx+=1
    K = int(data[idx]); idx+=1
    edges = []
    adj = [[] for _ in range(N+1)]
    for _ in range(M):
        u = int(data[idx]); idx+=1
        v = int(data[idx]); idx+=1
        edges.append((u,v))
        adj[u].append(v)
    # unweighted shortest path length L from 1 to N
    dist = [-1]*(N+1); dist[1]=0
    q = deque([1])
    while q:
        x = q.popleft()
        for y in adj[x]:
            if dist[y]<0:
                dist[y]=dist[x]+1; q.append(y)
    L = dist[N]
    INF = 10**9
    def mincut(D):
        nn = N*D+2
        S = N*D; T = N*D+1
        graph = [[] for _ in range(nn)]
        def add(a,b,c):
            graph[a].append([b,c,len(graph[b])])
            graph[b].append([a,0,len(graph[a])-1])
        def nid(v,t): return (v-1)*D + (t-1)
        for t in range(1,D+1):
            add(S, nid(N,t), INF)
            add(nid(1,t), T, INF)
        for v in range(1,N+1):
            for t in range(1,D):
                add(nid(v,t+1), nid(v,t), INF)
        for (u,v) in edges:
            for t in range(2,D+1):
                add(nid(v,t), nid(u,t-1), INF)
            for t in range(1,D+1):
                add(nid(v,t), nid(u,t), 1)
        flow = 0
        while True:
            level = [-1]*nn
            level[S]=0
            bq = deque([S])
            while bq:
                x = bq.popleft()
                for e in graph[x]:
                    if e[1]>0 and level[e[0]]<0:
                        level[e[0]] = level[x]+1
                        bq.append(e[0])
            if level[T]<0:
                return flow
            it = [0]*nn
            def dfs(x,f):
                if x==T: return f
                while it[x] < len(graph[x]):
                    e = graph[x][it[x]]
                    if e[1]>0 and level[e[0]]==level[x]+1:
                        d = dfs(e[0], min(f,e[1]))
                        if d>0:
                            e[1]-=d
                            graph[e[0]][e[2]][1]+=d
                            return d
                    it[x]+=1
                return 0
            while True:
                f = dfs(S, INF)
                if f==0: break
                flow += f
                if flow > K:
                    # already exceeds K, can stop early (cut >= flow)
                    return flow
        return flow
    ans = 0
    for D in range(L, 0, -1):
        if mincut(D) <= K:
            ans = D
            break
    print(ans)
