from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # For each pair (a,b) with a<b, register a at index b
        at = [[] for _ in range(n + 1)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            at[b].append(a)

        max1 = 0  # largest 'a' among pairs whose b <= current i
        max2 = 0  # second largest
        base = 0
        improve = [0] * (n + 1)  # gain if we remove the pair contributing value max1

        for i in range(1, n + 1):
            for a in at[i]:
                if a > max1:
                    max2 = max1
                    max1 = a
                elif a > max2:
                    max2 = a
            # valid subarrays ending at i: left endpoint must be > max1
            base += i - max1
            # if the pair giving max1 were removed, bound would be max2
            improve[max1] += max1 - max2

        return base + max(improve)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [None] * L
        prev = -1  # last T index processed
        for i, c in enumerate(str1):
            if c != 'T':
                continue
            if prev >= 0 and i - prev < m:
                d = i - prev
                # overlap consistency: existing suffix comes from window at prev
                if str2[d:] != str2[:m - d]:
                    return ""
                # fill only the new tail part: positions prev+m .. i+m-1
                start = prev + m
                seg = str2[m - d:]
                for k in range(len(seg)):
                    word[start + k] = seg[k]
            else:
                for k in range(m):
                    word[i + k] = str2[k]
            prev = i

        free = [w is None for w in word]
        for idx in range(L):
            if word[idx] is None:
                word[idx] = 'a'

        s2 = list(str2)

        # Greedy pass(es): break any F-window equal to str2 by setting the
        # rightmost free position in that window to 'b'. Repeat until stable
        # (normally the second pass is just verification).
        passes = 0
        while True:
            passes += 1
            changed = False
            for i in range(n):
                if str1[i] == 'F' and word[i:i + m] == s2:
                    j = i + m - 1
                    while j >= i and not free[j]:
                        j -= 1
                    if j < i:
                        return ""
                    word[j] = 'b'
                    free[j] = False
                    changed = True
            if not changed:
                break
            if passes > L + 2:  # safety bound (cannot actually be reached)
                return ""

        return "".join(word)

