class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Precompute factorials (capped comparison not needed; Python big ints ok for n<=100)
        fact = [1] * (n + 2)
        for i in range(1, n + 2):
            fact[i] = fact[i - 1] * i

        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))

        def count(o, e, start):
            # number of alternating permutations with o odds, e evens remaining,
            # where the next element must have parity `start` (1=odd, 0=even)
            if o + e == 0:
                return 1
            if start == 1:
                if o == e or o == e + 1:
                    return fact[o] * fact[e]
                return 0
            else:
                if e == o or e == o + 1:
                    return fact[o] * fact[e]
                return 0

        res = []
        req = None  # required parity of next element; None means any (first position)

        for _ in range(n):
            if req is None:
                candidates = sorted(odds + evens)
            elif req == 1:
                candidates = odds
            else:
                candidates = evens

            placed = False
            for x in candidates:
                p = x % 2
                o = len(odds) - (1 if p == 1 else 0)
                e = len(evens) - (1 if p == 0 else 0)
                if o + e == 0:
                    c = 1
                else:
                    c = count(o, e, 1 - p)
                if c == 0:
                    continue
                if k <= c:
                    res.append(x)
                    if p == 1:
                        odds.remove(x)
                    else:
                        evens.remove(x)
                    req = 1 - p
                    placed = True
                    break
                else:
                    k -= c

            if not placed:
                return []

        return res

