class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        P = 4 * s
        pos = []
        for x, y in points:
            if y == 0:
                p = x
            elif x == s:
                p = s + y
            elif y == s:
                p = 3 * s - x
            else:  # x == 0
                p = 4 * s - y
            pos.append(p)
        pos.sort()
        n = len(pos)
        m = 2 * n
        INF = float('inf')
        pos2 = pos + [q + P for q in pos] + [INF]

        def feasible(d):
            # nxt[i] = first index j >= i with pos2[j] >= pos2[i] + d (two pointers)
            nxt = [m] * (m + 1)
            j = 0
            for i in range(m):
                need = pos2[i] + d
                while j < m and pos2[j] < need:
                    j += 1
                nxt[i] = j
            # nxt[m] = m sentinel already (INF position)
            res = list(range(n))
            steps = k - 1
            table = nxt
            while True:
                if steps & 1:
                    res = [table[x] for x in res]
                steps >>= 1
                if not steps:
                    break
                table = [table[x] for x in table]
            lim = P - d
            p2 = pos2
            for i in range(n):
                if p2[res[i]] - pos[i] <= lim:
                    return True
            return False

        lo, hi = 1, P // k
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

