class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise cycle
        G = [[[0] * m for _ in range(n)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            gd = G[d]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            for i in rows:
                gi = grid[i]; gdi = gd[i]
                ni = i + dr
                inrow = 0 <= ni < n
                if inrow:
                    gni = grid[ni]; gdni = gd[ni]
                for j in range(m):
                    v = gi[j]
                    if v == 1:
                        continue
                    nj = j + dc
                    if inrow and 0 <= nj < m and gni[nj] == 2 - v:
                        gdi[j] = 1 + gdni[nj]
                    else:
                        gdi[j] = 1
        M = [[[0] * m for _ in range(n)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            d2 = (d + 1) % 4
            dr2, dc2 = dirs[d2]
            Gd2 = G[d2]; Md = M[d]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            for i in rows:
                gi = grid[i]; Mdi = Md[i]
                ni = i + dr; ni2 = i + dr2
                inrow = 0 <= ni < n
                inrow2 = 0 <= ni2 < n
                if inrow:
                    gni = grid[ni]; Mdni = Md[ni]
                if inrow2:
                    gni2 = grid[ni2]; Gd2ni2 = Gd2[ni2]
                for j in range(m):
                    v = gi[j]
                    if v == 1:
                        continue
                    w = 2 - v
                    t = 0
                    nj2 = j + dc2
                    if inrow2 and 0 <= nj2 < m and gni2[nj2] == w:
                        t = Gd2ni2[nj2]
                    nj = j + dc
                    if inrow and 0 <= nj < m and gni[nj] == w:
                        x = 1 + Mdni[nj]
                        if x > t:
                            t = x
                    Mdi[j] = t
        ans = 0
        for i in range(n):
            gi = grid[i]
            for j in range(m):
                if gi[j] == 1:
                    if ans < 1:
                        ans = 1
                    for d, (dr, dc) in enumerate(dirs):
                        ni = i + dr; nj = j + dc
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2:
                            c = 1 + G[d][ni][nj]
                            if c > ans:
                                ans = c
                            c = 2 + M[d][ni][nj]
                            if c > ans:
                                ans = c
        return ans

