class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        p1 = p[:i1]
        p2 = p[i1+1:i2]
        p3 = p[i2+1:]
        L1, L2, L3 = len(p1), len(p2), len(p3)

        def find_occ(text, pat):
            # returns sorted list of starting indices of pat in text
            m = len(pat)
            if m == 0:
                return list(range(len(text) + 1))
            if m > len(text):
                return []
            # KMP failure function
            fail = [0] * m
            k = 0
            for i in range(1, m):
                while k > 0 and pat[i] != pat[k]:
                    k = fail[k-1]
                if pat[i] == pat[k]:
                    k += 1
                fail[i] = k
            res = []
            k = 0
            for i, c in enumerate(text):
                while k > 0 and c != pat[k]:
                    k = fail[k-1]
                if c == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = fail[k-1]
            return res

        occ1 = find_occ(s, p1)
        occ2 = find_occ(s, p2)
        occ3 = find_occ(s, p3)

        if not occ1 or not occ2 or not occ3:
            return -1

        INF = float('inf')
        best = INF
        for j in occ2:
            # largest start i in occ1 with i + L1 <= j
            idx = bisect.bisect_right(occ1, j - L1) - 1
            if idx < 0:
                continue
            i = occ1[idx]
            # smallest start k in occ3 with k >= j + L2
            idx2 = bisect.bisect_left(occ3, j + L2)
            if idx2 >= len(occ3):
                continue
            k = occ3[idx2]
            length = k + L3 - i
            if length < best:
                best = length

        return best if best != INF else -1

