class Solution:
    def countSubstrings(self, s: str) -> int:
        ans = 0
        c3 = [1, 0, 0]          # counts of prefix digit-sums mod 3 (pre[-1] = 0)
        c9 = [1, 0, 0, 0, 0, 0, 0, 0, 0]  # counts of prefix digit-sums mod 9
        p3 = 0
        p9 = 0
        has7 = '7' in s
        cnt7 = [0] * 7          # counts of substrings ending at current pos by value mod 7

        for i, ch in enumerate(s):
            d = ord(ch) - 48
            p3 = (p3 + d) % 3
            p9 = (p9 + d) % 9

            if has7:
                new7 = [0] * 7
                for r in range(7):
                    v = cnt7[r]
                    if v:
                        new7[(10 * r + d) % 7] += v
                new7[d % 7] += 1
                cnt7 = new7

            if d == 0:
                pass
            elif d == 1 or d == 2 or d == 5:
                # divisibility by 1 always; by 2 last digit even; by 5 last digit 5
                ans += i + 1
            elif d == 3 or d == 6:
                # by 3: digit sum mod 3 == 0; by 6: even (last digit 6) + digit sum mod 3
                ans += c3[p3]
            elif d == 9:
                ans += c9[p9]
            elif d == 4:
                # mod 4 depends on last two digits
                ans += 1  # "4" itself
                if i >= 1 and (ord(s[i-1]) - 48) % 2 == 0:
                    ans += i  # all substrings of length >= 2
            elif d == 8:
                # mod 8 depends on last three digits
                ans += 1  # "8" itself
                if i >= 1:
                    if ((ord(s[i-1]) - 48) * 10 + 8) % 8 == 0:
                        ans += 1  # length exactly 2
                if i >= 2:
                    if ((ord(s[i-2]) - 48) * 100 + (ord(s[i-1]) - 48) * 10 + 8) % 8 == 0:
                        ans += i - 1  # all substrings of length >= 3
            elif d == 7:
                ans += cnt7[0]

            c3[p3] += 1
            c9[p9] += 1

        return ans

