class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(t: int) -> bool:
            # minimum moves to make every gameScore[i] >= t
            if t == 0:
                return True
            moves = 0
            prev_extra = 0  # visits already granted to current index by bouncing from previous
            for i in range(n):
                p = points[i]
                need = (t + p - 1) // p  # total visits needed at i
                need -= prev_extra
                if need <= 0:
                    if i == n - 1:
                        break
                    # still must pass through
                    moves += 1
                    prev_extra = 0
                else:
                    # 1 move to step in, then 2 moves per extra visit (bounce i -> i+1 -> i)
                    moves += 1 + 2 * (need - 1)
                    prev_extra = need - 1
                if moves > m:
                    return False
            return moves <= m

        lo, hi = 0, ((m + 1) // 2) * max(points)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

