def main():
    N, P = map(int, sys.stdin.buffer.read().split())
    D = N * (N - 1) // 2
    half = N // 2
    maxrow = max(N, half * (half - 1) // 2) + 1
    pas = [[1]]
    for n in range(1, maxrow + 1):
        prev = pas[-1]
        pas.append([1] + [prev[i - 1] + prev[i] for i in range(1, n)] + [1])

    def pack(coeffs):
        return int.from_bytes(b''.join(c.to_bytes(16, 'little') for c in coeffs), 'little')

    def unpack_mod(x, ln):
        b = x.to_bytes(16 * ln, 'little')
        fb = int.from_bytes
        return [fb(b[i:i + 16], 'little') % P for i in range(0, 16 * ln, 16)]

    def polymul_mod(a, b):
        return unpack_mod(pack(a) * pack(b), len(a) + len(b) - 1)

    # T[j][k] = ((1+x)^j - 1)^k * (1+x)^{C(k,2)} mod P, packed
    Tpk = {}
    for j in range(1, half + 1):
        Aj = [c % P for c in pas[j]]
        Aj[0] = (Aj[0] - 1) % P
        cur = [1]
        for k in range(1, half + 1):
            cur = polymul_mod(cur, Aj)
            m = k * (k - 1) // 2
            pw = [c % P for c in pas[m]]
            Tpk[(j, k)] = pack(polymul_mod(cur, pw))

    # levels[u]: dict (e, j, p) -> packed polynomial (unreduced accumulation)
    levels = [dict() for _ in range(N + 1)]
    levels[1][(1, 1, 0)] = 1
    for u in range(1, N):
        lvl = levels[u]
        if not lvl:
            continue
        cap = min(D, u * (u - 1) // 2) + 1
        rem = N - u
        prow = pas[rem]
        for (e, j, p), val in lvl.items():
            val = pack(unpack_mod(val, cap))  # reduce mod P
            if not val:
                continue
            o = u - e
            q = 1 - p
            maxk = (half - e) if q == 0 else (half - o)
            for k in range(1, maxk + 1):
                s = prow[k] % P
                contrib = val * Tpk[(j, k)] * s
                ne = e + k if q == 0 else e
                key = (ne, k, q)
                t = levels[u + k]
                if key in t:
                    t[key] += contrib
                else:
                    t[key] = contrib

    acc = 0
    for (e, j, p), val in levels[N].items():
        if e == half:
            acc += val
    coeffs = unpack_mod(acc, D + 1)
    sys.stdout.write(' '.join(map(str, coeffs[N - 1:])) + '\n')

