                    if S[x+got:x+got+h] == T[y+got:y+got+h]:
                        got += h
                        s -= h
                    else:
                        s = h
                break
        return x + got

    NEG = -1 << 60
    target = n - m

    F = {0: snake(0, 0)}
    if n == m and F[0] == n:
        print("Yes")
        return

    for e in range(1, K + 1):
        newF = {}
        for d in range(-e, e + 1):
            best = NEG
            # substitution: from diagonal d
            v = F.get(d, NEG)
            if v != NEG and v < n and v - d < m:
                best = v + 1
            # deletion (consume S char): from diagonal d-1
            v = F.get(d - 1, NEG)
            if v != NEG and v < n:
                if v + 1 > best:
                    best = v + 1
            # insertion (consume T char): from diagonal d+1
            v = F.get(d + 1, NEG)
            if v != NEG and v - (d + 1) < m:
                if v > best:
                    best = v
            if best == NEG:
                continue
            newF[d] = snake(best, d)
        F = newF
        if F.get(target, NEG) >= n:
            print("Yes")
            return

    print("No")

main()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        # Check if answer 1 is achievable: make string alternating
        cost0 = sum(1 for i, c in enumerate(s) if int(c) != i % 2)      # pattern 0101...
        cost1 = n - cost0                                               # pattern 1010...
        if min(cost0, cost1) <= numOps:
            return 1

        # Compute run lengths
        runs = []
        cnt = 1
        for i in range(1, n):
            if s[i] == s[i - 1]:
                cnt += 1
            else:
                runs.append(cnt)
                cnt = 1
        runs.append(cnt)

        # For m >= 2, each run of length L needs floor(L / (m+1)) flips,
        # and these flips can always be placed so they don't create
        # new long runs (flipped chars are isolated singles, safe when m >= 2).
        def feasible(m):
            total = 0
            for L in runs:
                total += L // (m + 1)
                if total > numOps:
                    return False
            return total <= numOps

        lo, hi = 2, n
        ans = n
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

