class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        mx = max(cnt)
        n = len(s)
        ans = n  # delete everything -> empty string is good

        for k in range(1, mx + 1):
            # dp: mapping pass_amount -> min cost so far
            dp = {0: 0}
            for c in cnt:
                ndp = {}
                for p, cost in dp.items():
                    # Option 1: reduce this letter to 0
                    v = cost + c
                    np = c  # can pass up to c chars as conversions
                    if np not in ndp or ndp[np] > v:
                        ndp[np] = v
                    # Option 2: make this letter have exactly k
                    if c >= k:
                        v = cost + (c - k)
                        np = c - k
                    else:
                        v = cost + max(0, k - c - p)
                        np = 0
                    if np not in ndp or ndp[np] > v:
                        ndp[np] = v
                dp = ndp
            ans = min(ans, min(dp.values()))

        return ans

