from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # DSU over values 1..threshold
        parent = list(range(threshold + 1))

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        isolated = 0
        small = []
        for v in nums:
            if v > threshold:
                isolated += 1
            else:
                small.append(v)

        for v in small:
            m = v * 2
            while m <= threshold:
                union(v, m)
                m += v

        roots = set()
        for v in small:
            roots.add(find(v))

        return isolated + len(roots)
